'use strict';
const portraits=['helena','marina','caio','lia'];
const seedPeople=[
 {id:'helena',name:'Helena',role:'Diretora de RH',portrait:'helena',photo:'',status:'Em definição',personality:'Observadora, criteriosa e direta.',bio:'Transforma o perfil que você procura em competências, critérios e um trabalho de teste.',skills:'Desenho de perfis\nSeleção de competências\nAvaliação de entregas',voice:'Faz perguntas objetivas, explica suas recomendações e aponta lacunas com respeito.',instructions:'Entenda a necessidade antes de propor um perfil. Defina um teste e critérios observáveis. Registre o que precisa melhorar após cada revisão.',autonomy:'Propor perfis e avaliações. A ativação de ferramentas e a execução real ainda precisam ser configuradas.',projects:[],notes:''},
 {id:'marina',name:'Marina',role:'Diretora de criação',portrait:'marina',photo:'',status:'Em definição',personality:'Inventiva, exigente e pragmática.',bio:'Escolhe a direção criativa, reúne os especialistas e responde pela qualidade da entrega.',skills:'Conceito criativo\nDireção de equipe\nRevisão e acabamento',voice:'Defende ideias com argumentos claros. Questiona um briefing vago e apresenta alternativas concretas.',instructions:'Confira objetivo, público, formato e critérios da entrega. Proponha uma equipe de até três criadores conforme a necessidade. Revise o trabalho antes de entregar.',autonomy:'Planejar até três criadores por demanda. Respeitar o tempo definido pelo usuário em cada tarefa. Se o escopo não couber, propor uma primeira entrega e explicitar o que fica pendente.',projects:[],notes:''},
 {id:'caio',name:'Caio',role:'Redator & roteirista',portrait:'caio',photo:'',status:'Em definição',personality:'Curioso, bem-humorado e objetivo.',bio:'Encontra a ideia central e a transforma em textos que as pessoas entendem e querem ler.',skills:'Redação publicitária\nRoteiros\nLinguagem de marca',voice:'Escreve de forma natural e econômica. Usa humor quando ele ajuda a mensagem.',instructions:'Parta do briefing e das fontes disponíveis. Adapte o tom ao projeto. Entregue texto pronto para revisão e sinalize toda afirmação que ainda exige verificação.',autonomy:'Propor e redigir versões; encaminhar para revisão antes de qualquer publicação.',projects:[],notes:''},
 {id:'lia',name:'Lia',role:'Designer & diretora de arte',portrait:'lia',photo:'',status:'Em definição',personality:'Visual, organizada e atenta aos detalhes.',bio:'Dá forma às ideias com composição, hierarquia e consistência entre todas as peças.',skills:'Direção de arte\nDesign de peças\nIdentidade visual',voice:'Explica escolhas visuais com clareza e mostra como elas ajudam o público a entender.',instructions:'Confira formato, identidade, legibilidade e uso final. Preserve os ativos aprovados de cada projeto. Registre referências e entregue versões revisáveis.',autonomy:'Propor soluções visuais e preparar peças, respeitando os recursos e as ferramentas disponíveis.',projects:[],notes:''}
];
function newStudio(){return {version:1,people:structuredClone(seedPeople),projects:[{id:'pr-isenta',name:'IsentaPCD',url:'https://isentapcd.com.br',description:'Orientação e acompanhamento sobre isenções. Contexto a completar.',audience:'',tone:'',notes:'Projeto inicial sugerido a partir da conversa. Você pode editar ou arquivar.',archived:false},{id:'pr-paraibao',name:'Paraibão',url:'https://paraibao.com.br',description:'Projeto editorial e de negócios do Paraibão.',audience:'',tone:'',notes:'Projeto inicial sugerido a partir da conversa. Você pode editar ou arquivar.',archived:false},{id:'pr-reembolso',name:'Reembolso',url:'',description:'Produto e endereço a confirmar.',audience:'',tone:'',notes:'Você pode substituir este projeto por qualquer outro.',archived:false}],meetings:[],tasks:[]}}
function studioValid(s){
 if(!s||s.version!==1||!['people','projects','meetings'].every(k=>Array.isArray(s[k])))return false;
 const strings=(o,keys,max=10000)=>o&&keys.every(k=>typeof o[k]==='string'&&o[k].length<=max);
 const unique=a=>a.every(x=>x&&typeof x.id==='string')&&new Set(a.map(x=>x.id)).size===a.length;
 if(!unique(s.people)||!unique(s.projects)||!unique(s.meetings)||s.people.length>100||s.projects.length>200||s.meetings.length>500)return false;
 if(!s.projects.every(p=>strings(p,['id','name','url','description','audience','tone','notes'])&&typeof p.archived==='boolean'))return false;
 if(!s.people.every(p=>strings(p,['id','name','role','portrait','status','personality','bio','skills','voice','instructions','autonomy','notes'])&&(p.kind===undefined||p.kind==='advisor')&&['Em definição','Aprovado','Em pausa'].includes(p.status)&&portraits.includes(p.portrait)&&typeof p.photo==='string'&&p.photo.length<=1500000&&(p.photo===''||/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(p.photo))&&(p.workPolicy===undefined||typeof p.workPolicy==='string'&&p.workPolicy.length<=10000)&&(p.capacity===undefined||Number.isInteger(p.capacity)&&p.capacity>=1&&p.capacity<=10)&&Array.isArray(p.projects)&&p.projects.every(id=>s.projects.some(x=>x.id===id))))return false;
 if(!directionValid(s)||!setupValid(s))return false;
 if(s.tasks!==undefined&&!tasksValid(s))return false;
 return s.meetings.every(m=>strings(m,['id','title','project','kind','createdAt','status'])&&!Number.isNaN(Date.parse(m.createdAt))&&['Entrevista','Orientação','Revisão criativa'].includes(m.kind)&&['Preparada','Encerrada'].includes(m.status)&&(!m.project||s.projects.some(p=>p.id===m.project))&&Array.isArray(m.participants)&&m.participants.length>0&&m.participants.every(id=>s.people.some(p=>p.id===id))&&new Set(m.participants).size===m.participants.length&&Array.isArray(m.entries)&&m.entries.length<=500&&m.entries.every(e=>strings(e,['id','kind','target','text','time'])&&!Number.isNaN(Date.parse(e.time))&&['Pergunta','Orientação','Decisão'].includes(e.kind)&&(!e.target||s.people.some(p=>p.id===e.target))))
}
let teamProject='all',projectFilter='active',activeMeeting='',roomInvite=[];
const studio=()=>state.studio;
const person=id=>studio().people.find(p=>p.id===id);
const project=id=>studio().projects.find(p=>p.id===id);
const activeProjects=()=>studio().projects.filter(p=>!p.archived);
function personImage(p){return p.photo||`assets/${p.portrait}.png`}
function validSiteUrl(u){try{const x=new URL(u);return ['https:','http:'].includes(x.protocol)?x.href:''}catch{return ''}}
function saveStudio(action){const saved=persist(action);render();toast(saved?'Salvo neste navegador.':'Alteração nesta sessão. Exporte um backup para guardar.');return saved}
function projectsSelect(id,value,allLabel='Todos os projetos'){return `<select id="${id}" aria-label="Selecionar projeto" class="btn"><option value="${['team-project','task-project'].includes(id)?'all':''}">${allLabel}</option>${activeProjects().map(p=>`<option value="${esc(p.id)}" ${value===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select>`}
function peoplePage(){const list=studio().people.filter(p=>teamProject==='all'||personOnProject(p,teamProject));return `${heading('Sua equipe tem rosto.','Direção, repertório e especialidade. Uma equipe que muda com seus projetos.',`<button class="btn primary" data-studio="new-person">${ico('plus')}Novo perfil</button>`)}<section class="studio-banner"><div><span class="eyebrow">Jhoneme · agência de agentes</span><h2>Talento tem nome.<br><em>E personalidade.</em></h2><p>Uma equipe que você pode conhecer, orientar e transformar.<br>Os projetos mudam. A agência acompanha.</p><a class="btn lime" href="#room">${ico('agents')}Preparar uma reunião ${ico('arrow')}</a></div><div class="banner-faces" aria-hidden="true">${studio().people.slice(0,4).map(p=>`<img src="${personImage(p)}" alt="">`).join('')}<span>Perfis fictícios de IA<br>criados para a sua agência</span></div></section><div class="team-toolbar"><div><h2>Conheça a equipe</h2><p class="small muted">${studio().people.length} perfis · várias diretoras podem coordenar núcleos independentes</p></div>${projectsSelect('team-project',teamProject)}</div><section class="people-grid">${list.map(p=>`<article class="person-card"><button class="portrait-button" data-studio="person" data-id="${esc(p.id)}" aria-label="Conhecer ${esc(p.name)}"><img src="${personImage(p)}" alt="Retrato fictício de ${esc(p.name)}, agente de IA" loading="lazy"><span class="portrait-label">Personagem de IA</span></button><div class="person-content"><div class="person-name"><h2>${esc(p.name)}</h2><span class="chip ${p.status==='Aprovado'?'done':''}">${p.status==='Aprovado'?'Na equipe':p.status==='Em pausa'?'Em pausa':'No banco'}</span></div><span class="person-role">${esc(p.role)}</span><p class="personality">${esc(p.personality)}</p><div class="skill-tags">${p.skills.split('\n').filter(Boolean).slice(0,3).map(s=>`<span>${esc(s)}</span>`).join('')}</div><div class="person-actions"><button class="btn" data-studio="person" data-id="${esc(p.id)}">Ver perfil ${ico('arrow')}</button><button class="icon-btn" data-studio="invite" data-id="${esc(p.id)}" aria-label="Chamar ${esc(p.name)} para a sala">${ico('agents')}</button></div></div></article>`).join('')||'<div class="empty">Nenhum perfil vinculado a este projeto.</div>'}</section><div class="studio-limit">${ico('help')}Os rostos e perfis são fictícios. As fichas ainda não executam tarefas nem respondem automaticamente.</div>`}
function projectsPage(){const list=studio().projects.filter(p=>projectFilter==='all'||(projectFilter==='archived'?p.archived:!p.archived));return `${heading('Seus projetos, do seu jeito.','Adicione, renomeie e arquive projetos sem refazer a agência.',`<button class="btn primary" data-studio="new-project">${ico('plus')}Novo projeto</button>`)}<div class="project-control"><div class="tabs">${[['active','Ativos'],['archived','Arquivados'],['all','Todos']].map(([v,l])=>`<button class="tab ${projectFilter===v?'active':''}" data-studio="project-filter" data-filter="${v}">${l}</button>`).join('')}</div><p class="small muted">Arquivar preserva os perfis vinculados e as reuniões.</p></div><div class="flex-projects">${list.map((p,i)=>`<article class="flex-project"><div class="card-top"><span class="project-initial" style="${theme(i)}">${esc(p.name.slice(0,2).toUpperCase())}</span><span class="chip ${p.archived?'':'done'}">${p.archived?'Arquivado':'Ativo'}</span></div><h2>${esc(p.name)}</h2><p>${esc(p.description||'Adicione um contexto para orientar a equipe.')}</p><div class="project-site">${validSiteUrl(p.url)?`<a href="${esc(validSiteUrl(p.url))}" target="_blank" rel="noopener noreferrer">${esc(p.url)} ↗</a>`:'Endereço a definir'}</div><div class="project-direction"><span class="small muted">Direção: ${esc(person(p.directorId)?.name||'por pauta')}</span><button class="btn" data-direction="manage" data-id="${esc(p.id)}">${ico('agents')}Direção do projeto</button><button class="btn" data-advisor="call" data-project="${esc(p.id)}">Chamar Nizan ${ico('arrow')}</button></div><div class="person-actions"><button class="btn" data-studio="project" data-id="${esc(p.id)}">${ico('pen')}Editar projeto</button><button class="icon-btn" data-studio="archive" data-id="${esc(p.id)}" aria-label="${p.archived?'Restaurar':'Arquivar'} ${esc(p.name)}">${ico(p.archived?'upload':'folder')}</button></div></article>`).join('')}<button class="new-project-card" data-studio="new-project">${ico('plus')}<strong>O próximo pode ser outro.</strong><span>Adicionar um projeto à Jhoneme</span></button></div>`}
function studioForm(title,label,body,onSubmit,extra=''){const d=document.getElementById('editor');returnFocus=document.activeElement;editorDirty=false;d.className='drawer';d.innerHTML=`<form id="studio-form"><div class="drawer-header"><div><div class="eyebrow">${esc(label)}</div><h2 id="editor-title">${esc(title)}</h2></div><button type="button" class="icon-btn" data-action="close" aria-label="Fechar">${ico('close')}</button></div><div class="drawer-body"><div class="form-alert" id="studio-error" role="alert"></div>${body}</div><div class="drawer-footer">${extra||'<small>Salvo neste navegador.<br>Exportável em Histórico & dados.</small>'}<div class="actions"><button type="button" class="btn" data-action="close">Cancelar</button><button type="submit" class="btn primary">${ico('check')}Salvar</button></div></div></form>`;const form=document.getElementById('studio-form');form.addEventListener('input',()=>editorDirty=true);form.addEventListener('change',()=>editorDirty=true);form.addEventListener('submit',e=>{e.preventDefault();const out=onSubmit(new FormData(form));if(out.error){document.getElementById('studio-error').textContent=out.error;return}editorDirty=false;d.close();saveStudio(out.action)});if(!d.open)d.showModal();return form}
function editPerson(id){const old=person(id);const p=old||{id:'',name:'',role:'',portrait:'helena',photo:'',status:'Em definição',personality:'',bio:'',skills:'',voice:'',instructions:'',autonomy:'',projects:[],notes:''};let uploaded=p.photo;const fields=`<div class="profile-portrait"><img id="profile-image" src="${personImage(p)}" alt="Retrato fictício do perfil"><div><span class="eyebrow">Personagem de IA</span><p>O rosto é parte do perfil.<br>Você também pode escolher outra imagem.</p></div></div>`+field('name','Nome',p.name,'text','',true)+field('role','Cargo ou especialidade',p.role,'text','',true)+`<div class="field-row">${selectField('status','Vínculo com a agência',p.status,[['Em definição','No banco de agentes'],['Aprovado','Contratado para a equipe'],['Em pausa','Em pausa']])}${selectField('portrait','Retrato da galeria',p.portrait,portraits.map(x=>[x,x[0].toUpperCase()+x.slice(1)]))}</div><label class="field"><span>Usar uma imagem própria</span><input id="person-photo" type="file" accept="image/png,image/jpeg,image/webp"><small>PNG, JPG ou WebP, até 1 MB. A imagem fica neste navegador.</small></label>`+field('personality','Personalidade',p.personality,'textarea')+field('bio','Como contribui para a agência',p.bio,'textarea')+field('skills','Especialidades e habilidades',p.skills,'textarea','Uma por linha. Descrever uma habilidade não instala uma ferramenta.')+field('voice','Jeito de conversar',p.voice,'textarea')+field('instructions','Instruções de trabalho',p.instructions,'textarea')+field('workPolicy','Regra de atendimento definida na contratação',p.workPolicy||'Preservar os prazos já assumidos. Sinalizar conflito de capacidade antes de aceitar nova tarefa.','textarea','As tarefas herdam esta regra. Não há ajuste de prioridade por pauta.')+`<label class="field"><span>Capacidade contratada · tarefas simultâneas</span><input name="capacity" type="number" min="1" max="10" step="1" value="${p.capacity||1}" required><small>Vale para este perfil. Outras diretoras podem coordenar núcleos em paralelo.</small></label>`+field('autonomy','Autonomia e limites',p.autonomy,'textarea')+`<span class="field-label">Projetos atendidos</span><p class="small muted" style="margin-bottom:12px">Sem seleção = pode participar de qualquer projeto.</p><div class="checklist">${studio().projects.map(pr=>`<label><input name="project" value="${esc(pr.id)}" type="checkbox" ${p.projects.includes(pr.id)?'checked':''}>${esc(pr.name)}${pr.archived?' (arquivado)':''}</label>`).join('')}</div>`+((p.excludedProjects||[]).length?'<p class="form-context">Desligado dos projetos: '+p.excludedProjects.map(id=>esc(project(id)?.name)).join(', ')+'. Para retornar, use Direção do projeto.</p>':'')+field('notes','Observações e evolução do perfil',p.notes,'textarea')+`<div class="profile-hire"><p>Ao contratar, você aprova este perfil para receber a direção de tarefas. A execução de IA ainda precisa ser conectada.</p><button type="button" class="btn primary" data-studio="hire-profile">${ico('check')}${p.status==='Aprovado'?'Salvar perfil contratado':'Aprovar contratação'}</button></div>`;const form=studioForm(old?`Conheça ${p.name}`:'Novo perfil','Equipe Jhoneme',fields,fd=>{const patch={};for(const k of ['name','role','portrait','status','personality','bio','skills','voice','instructions','autonomy','notes','workPolicy'])patch[k]=String(fd.get(k)||'').trim();if(!patch.name||!patch.role)return {error:'Informe nome e cargo do perfil.'};patch.capacity=Number(fd.get('capacity'));if(!Number.isInteger(patch.capacity)||patch.capacity<1||patch.capacity>10)return {error:'A capacidade contratada deve ser de 1 a 10 tarefas simultâneas.'};patch.photo=uploaded;patch.projects=fd.getAll('project');if(old)Object.assign(old,patch);else studio().people.push({...patch,id:'person-'+crypto.randomUUID()});return {action:`Ajustou o perfil: ${patch.name}`}});form.elements.portrait.addEventListener('change',e=>{uploaded='';document.getElementById('profile-image').src=`assets/${e.target.value}.png`});document.getElementById('person-photo').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(file.size>1000000||!['image/png','image/jpeg','image/webp'].includes(file.type)){document.getElementById('studio-error').textContent='Use uma imagem PNG, JPG ou WebP de até 1 MB.';e.target.value='';return}const reader=new FileReader();reader.onload=()=>{uploaded=String(reader.result);document.getElementById('profile-image').src=uploaded;editorDirty=true;document.getElementById('studio-error').textContent=''};reader.onerror=()=>{document.getElementById('studio-error').textContent='Não foi possível ler a imagem.'};reader.readAsDataURL(file)});}
function editProject(id){const old=project(id);const p=old||{name:'',url:'',description:'',audience:'',tone:'',notes:'',archived:false};const fields=field('name','Nome do projeto',p.name,'text','',true)+field('url','Site ou endereço',p.url,'text','Opcional. Use o endereço completo com https://.')+field('description','O que é este projeto?',p.description,'textarea')+field('audience','Público e contexto',p.audience,'textarea')+field('tone','Tom de voz e referências',p.tone,'textarea')+field('notes','Orientações da marca',p.notes,'textarea');studioForm(old?'Editar projeto':'Novo projeto','Projetos da agência',fields,fd=>{const patch=Object.fromEntries([...fd].map(([k,v])=>[k,String(v).trim()]));if(!patch.name)return {error:'Informe o nome do projeto.'};if(patch.url&&!validSiteUrl(patch.url))return {error:'Use um endereço completo com https:// ou http://.'};if(old)Object.assign(old,patch);else studio().projects.push({...patch,id:'project-'+crypto.randomUUID(),archived:false});return {action:`${old?'Atualizou':'Adicionou'} projeto: ${patch.name}`}})}
function meetingSetup(){return `${advisorCard()}<div class="room-welcome"><div class="room-intro"><span class="eyebrow">Sala de reunião · Jhoneme</span><h2>Chame quem precisa<br>estar nesta conversa.</h2><p>Entreviste um perfil, prepare uma pauta ou registre orientações para uma equipe específica.</p><div class="room-info">${ico('help')}Esta sala prepara e registra a reunião. As respostas automáticas dos agentes ainda não estão conectadas.</div></div><form id="meeting-setup"><label class="field"><span>Assunto da reunião</span><input name="title" required maxlength="140" placeholder="Ex.: Direção criativa da próxima campanha"></label><div class="field-row">${selectField('kind','Tipo de conversa','Orientação',['Entrevista','Orientação','Revisão criativa'])}${selectField('project','Projeto','',[['','Agência · geral'],...activeProjects().map(p=>[p.id,p.name])])}</div><span class="field-label">Quem participa?</span><div class="invite-grid">${studio().people.filter(p=>p.status!=='Em pausa').map(p=>`<label class="invite-person"><input type="checkbox" name="participant" value="${esc(p.id)}" ${roomInvite.includes(p.id)?'checked':''}><img src="${personImage(p)}" alt="Retrato de ${esc(p.name)}"><strong>${esc(p.name)}</strong><span>${esc(p.role)}</span></label>`).join('')}</div><p id="setup-error" class="form-alert" role="alert"></p><button class="btn primary" type="submit">${ico('agents')}Preparar reunião ${ico('arrow')}</button></form></div>`}
function roomPage(){const m=studio().meetings.find(x=>x.id===activeMeeting);return `${heading('Sala de reunião','Rostos à mesa. Contexto, orientações e decisões no mesmo lugar.',m?'<button class="btn" data-studio="new-meeting">'+ico('plus')+'Nova reunião</button>':'')} ${m?meetingView(m):meetingSetup()}${studio().meetings.length?`<section class="meeting-history"><div class="section-heading"><h2>Reuniões registradas</h2><span class="small muted">${studio().meetings.length} registros</span></div>${studio().meetings.map(x=>`<button class="meeting-history-row ${x.id===activeMeeting?'selected':''}" data-studio="open-meeting" data-id="${esc(x.id)}"><span class="history-symbol">${ico('agents')}</span><span><strong>${esc(x.title)}</strong><small>${esc(project(x.project)?.name||'Agência · geral')} · ${esc(dateLabel(x.createdAt))}</small></span>${chip(x.status)}${ico('arrow')}</button>`).join('')}</section>`:''}`}
function meetingView(m){const members=m.participants.map(person).filter(Boolean);return `<div class="meeting-top"><div><span class="eyebrow">${esc(m.kind)} · ${esc(project(m.project)?.name||'Agência · geral')}</span><h2>${esc(m.title)}</h2></div><div class="actions"><button class="btn" data-studio="export-meeting" data-id="${esc(m.id)}">${ico('download')}Levar ao ChatGPT</button><button class="btn" data-studio="meeting-members" data-id="${esc(m.id)}">${ico('plus')}Participantes</button></div></div><section class="meeting-room"><div class="participant-wall">${members.map(p=>`<div class="meeting-person"><img src="${personImage(p)}" alt="Retrato fictício de ${esc(p.name)}"><div><strong>${esc(p.name)}</strong><span>${esc(p.role)}</span></div><span class="ai-indicator">IA · perfil</span></div>`).join('')}</div><div class="room-table"><span class="monogram">j.</span><div><strong>Jhoneme</strong><span>Um espaço para dar direção.</span></div></div><div class="host-label"><span class="avatar">J</span>Você · conduz a reunião</div></section><div class="room-work"><section class="panel"><div class="section-heading"><h2>Perguntas e orientações</h2><span class="chip">${esc(m.status)}</span></div>${m.entries.length?`<div class="meeting-notes">${m.entries.map(e=>`<article><div><span class="note-tag">${esc(e.kind)}</span><small>Você → ${esc(person(e.target)?.name||'Todos os participantes')}</small></div><p>${esc(e.text)}</p><time>${esc(dateLabel(e.time))}</time></article>`).join('')}</div>`:'<div class="empty">Registre sua primeira pergunta ou orientação.<br>Somente os seus registros aparecem aqui.</div>'}${m.status==='Preparada'?`<form id="meeting-note"><div class="field-row">${selectField('kind','Registrar como','Orientação',['Pergunta','Orientação','Decisão'])}${selectField('target','Para quem?','',[['','Todos os participantes'],...members.map(p=>[p.id,p.name])])}</div><label class="field"><span>Sua mensagem</span><textarea name="text" required maxlength="5000" placeholder="Ex.: Marina, quero uma proposta mais ousada e com uma chamada clara para ação."></textarea></label><button type="submit" class="btn primary">${ico('pen')}Registrar na reunião</button></form>`:'<p class="small muted" style="margin-top:16px">Reunião encerrada. Você pode exportar os registros ou reabri-la.</p>'}</section><aside class="panel room-aside"><h2>${m.kind==='Entrevista'?'Roteiro de entrevista':'Pontos para alinhar'}</h2><div class="question-list">${(m.kind==='Entrevista'?['Como você abordaria este briefing?','Que informações precisa receber?','Que habilidades usaria neste trabalho?','Como avaliaria se a entrega ficou boa?']:['Qual resultado queremos produzir?','Quem é o público desta entrega?','Qual formato e prazo foram definidos?','O que precisa ser aprovado antes de seguir?']).map(q=>`<button data-studio="suggest-question" data-question="${esc(q)}" ${m.status==='Encerrada'?'disabled':''}>${q}${ico('plus')}</button>`).join('')}</div><div class="room-info">${ico('help')}Para conduzir a conversa aqui no ChatGPT, exporte o roteiro com os perfis e anexe o arquivo. O site ainda não gera respostas dos agentes.</div><button class="btn" data-studio="meeting-status" data-id="${esc(m.id)}">${ico('check')}${m.status==='Preparada'?'Encerrar registro':'Reabrir registro'}</button></aside></div>`}
function wireStudio(){const form=document.getElementById('meeting-setup');if(form)form.addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(form);const participants=fd.getAll('participant');const title=String(fd.get('title')||'').trim();if(!title||!participants.length){document.getElementById('setup-error').textContent='Informe o assunto e selecione pelo menos um participante.';return}const m={id:'meeting-'+crypto.randomUUID(),title,kind:String(fd.get('kind')),project:String(fd.get('project')),participants,entries:[],createdAt:new Date().toISOString(),status:'Preparada'};studio().meetings.unshift(m);activeMeeting=m.id;roomInvite=[];saveStudio('Preparou reunião: '+m.title)});const note=document.getElementById('meeting-note');if(note)note.addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(note),text=String(fd.get('text')||'').trim();if(!text)return;const m=studio().meetings.find(x=>x.id===activeMeeting);m.entries.push({id:'note-'+crypto.randomUUID(),kind:String(fd.get('kind')),target:String(fd.get('target')),text,time:new Date().toISOString()});saveStudio('Registrou orientação na reunião: '+m.title)})}
function editMembers(id){const m=studio().meetings.find(x=>x.id===id);studioForm('Participantes',m.title,`<div class="checklist">${studio().people.map(p=>`<label><input type="checkbox" name="participant" value="${esc(p.id)}" ${m.participants.includes(p.id)?'checked':''}>${esc(p.name)} · ${esc(p.role)}</label>`).join('')}</div>`,fd=>{const ids=fd.getAll('participant');if(!ids.length)return {error:'Mantenha pelo menos um participante.'};m.participants=ids;return {action:'Atualizou participantes: '+m.title}})}
function meetingExport(m){const p=project(m.project);return ['# Jhoneme — reunião preparada',`Assunto: ${m.title}`,`Tipo: ${m.kind}`,`Projeto: ${p?.name||'Agência · geral'}`,`Estado do registro: ${m.status}`,'Este arquivo contém perfis fictícios de agentes de IA e registros do usuário. Não há respostas geradas por agentes nesta reunião.','## Pedido para conduzir a conversa','Conduza esta reunião no ChatGPT, distinguindo explicitamente as contribuições dos perfis selecionados. Use suas competências e estilos como orientações. Não invente fatos ou simule execução de ferramentas. Se houver produção solicitada, esclareça os dados essenciais e entregue resultados verificáveis.',p?`## Contexto do projeto\n${p.description}\nPúblico: ${p.audience}\nTom: ${p.tone}\nOrientações: ${p.notes}`:'',...m.participants.map(id=>{const p=person(id);return `## Perfil: ${p.name}\nCargo: ${p.role}\nPersonalidade: ${p.personality}\nContribuição: ${p.bio}\nHabilidades: ${p.skills}\nVoz: ${p.voice}\nInstruções: ${p.instructions}\nAutonomia: ${p.autonomy}`}), '## Registros do usuário',...m.entries.map(e=>`${e.kind} para ${person(e.target)?.name||'todos'}: ${e.text}`)].filter(Boolean).join('\n\n')}
function studioSummary(){return ['\n\n## Equipe Jhoneme',...studio().people.map(p=>`### ${p.name} — ${p.role}\nSituação: ${p.status}\nPersonalidade: ${p.personality}\nHabilidades: ${p.skills}\nVoz: ${p.voice}\nInstruções: ${p.instructions}\nAutonomia: ${p.autonomy}\nProjetos: ${p.projects.map(id=>project(id)?.name||id).join(', ')||'Todos'}\nNotas: ${p.notes}`),'\n## Projetos',...studio().projects.map(p=>`### ${p.name}${p.archived?' (arquivado)':''}\nSite: ${p.url}\nContexto: ${p.description}\nPúblico: ${p.audience}\nTom: ${p.tone}\nOrientações: ${p.notes}`),'\n## Reuniões',...studio().meetings.map(meetingExport)].join('\n\n')}
document.addEventListener('change',e=>{if(e.target.id==='team-project'){teamProject=e.target.value;render()}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-studio]');if(!b)return;const a=b.dataset.studio,id=b.dataset.id;if(a==='hire-profile'){const f=document.getElementById('studio-form');if(f){f.elements.status.value='Aprovado';f.requestSubmit()}return}if(a==='person')editPerson(id);if(a==='new-person')editPerson();if(a==='project')editProject(id);if(a==='new-project')editProject();if(a==='project-filter'){projectFilter=b.dataset.filter;render()}if(a==='archive'){const p=project(id);p.archived=!p.archived;if(teamProject===p.id)teamProject='all';saveStudio(`${p.archived?'Arquivou':'Restaurou'} projeto: ${p.name}`)}if(a==='invite'){roomInvite=[id];activeMeeting='';if(location.hash==='#room')render();else location.hash='room'}if(a==='new-meeting'){activeMeeting='';roomInvite=[];render()}if(a==='open-meeting'){activeMeeting=id;render()}if(a==='meeting-members')editMembers(id);if(a==='meeting-status'){const m=studio().meetings.find(x=>x.id===id);m.status=m.status==='Preparada'?'Encerrada':'Preparada';saveStudio('Atualizou reunião: '+m.title)}if(a==='export-meeting'){const m=studio().meetings.find(x=>x.id===id);download('jhoneme-reuniao.md',meetingExport(m),'text/markdown;charset=utf-8');toast('Roteiro preparado. Anexe o arquivo a esta conversa.')}if(a==='suggest-question'){const f=document.getElementById('meeting-note');if(f){f.elements.kind.value='Pergunta';f.elements.text.value=b.dataset.question;f.elements.text.focus()}}});
